(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-937":{scenario:{company:"Hợp tác xã Nông nghiệp Số Lâm Viên",supervisor:{name:"Phan Quốc Bảo",role:{vi:"Giám đốc Kỹ thuật canh tác",en:"Head of Crop Technology"}},ref_code:"GH-0314",title:{vi:"Đúng công thức. Đúng lượng tưới. Nông sản an toàn.",en:"Right recipe. Right irrigation. Safe produce."},brief:{vi:"Nhà màng GH-0314 trồng 3200 cây cà chua trên giá thể xơ dừa, đang ở tuần 14 sau trồng, chùm quả 1-3 đã đậu và bắt đầu chín. Cân lysimeter đo lượng nước cây hút trung bình 1.8 lít/cây/ngày; quy trình yêu cầu tỷ lệ nước thoát 25%. Đối chiếu cấu hình nháp của bộ điều khiển với hồ sơ canh tác đã duyệt, dùng terminal chẩn đoán, sửa công thức dinh dưỡng và tổng lượng tưới mỗi ngày, rồi lập báo cáo có căn cứ.",en:"Greenhouse GH-0314 grows 3200 tomato plants in coir substrate, now in week 14 after transplanting, with trusses 1-3 set and starting to ripen. The lysimeter shows average uptake of 1.8 liters per plant per day; the protocol requires a 25% drain fraction. Compare the controller's draft configuration with the approved crop plan, diagnose in the terminal, correct the nutrient recipe and the total daily irrigation volume, then write an evidence-based report."},reference_title:{vi:"Hồ sơ canh tác đã duyệt · GH-0314",en:"Approved crop plan · GH-0314"},fields:[{id:"RECIPE",label:{vi:"Công thức dinh dưỡng đang chạy",en:"Active nutrient recipe"},initial:"TOM-VEG",expected:"TOM-FRUIT",choices:["TOM-SEED","TOM-VEG","TOM-FRUIT"],reference:"Lịch dinh dưỡng theo giai đoạn",hint:{vi:"Từ khi chùm 1 đậu quả, cây chuyển sang giai đoạn nuôi quả và cần công thức tăng kali, canxi.",en:"Once truss 1 has set fruit the crop is generative and needs the higher potassium and calcium recipe."}},{id:"IRR_L_DAY",label:{vi:"Tổng lượng tưới mỗi ngày (lít)",en:"Total daily irrigation (liters)"},initial:"5760",expected:"7680",reference:"Bảng tính lượng tưới GH-0314",ref_value:{vi:"3200 cây; cây hút 1.8 lít/cây/ngày; tỷ lệ nước thoát mục tiêu 25%",en:"3200 plants; uptake 1.8 L/plant/day; target drain fraction 25%"},hint:{vi:"Lượng tưới phải bù cả phần nước thoát dùng để rửa muối khỏi giá thể.",en:"Irrigation must also cover the drain water that flushes salts out of the substrate."}}],sop32:{vi:"Lượng tưới mỗi cây = lượng cây hút / (1 - tỷ lệ nước thoát mục tiêu); tổng lượng tưới ngày = lượng tưới mỗi cây x số cây.",en:"Irrigation per plant = plant uptake / (1 - target drain fraction); total daily irrigation = irrigation per plant x number of plants."},context:{label:"BỘ ĐIỀU KHIỂN TƯỚI / GH-0314",metrics:[{label:{vi:"Số cây",en:"Plants"},value:"3,200"},{label:{vi:"Cây hút mỗi cây/ngày",en:"Uptake per plant/day"},value:"1.8 L"},{label:{vi:"Tỷ lệ nước thoát mục tiêu",en:"Target drain fraction"},value:"25%"}]},terminal:{system:"greenhouse-ctl",settable:["RECIPE","IRR_L_DAY"],commands:[{cmd:"status",out:{vi:"Nhà màng GH-0314: 3.200 cây cà chua, tuần 14 sau trồng; công thức đang chạy TOM-VEG; lượng tưới cài đặt 5.760 lít/ngày",en:"Greenhouse GH-0314: 3,200 tomato plants, week 14 after transplanting; active recipe TOM-VEG; irrigation setpoint 5,760 L/day"}},{cmd:"cat crop.log",out:{vi:"Tuần 9: chùm 1 đậu quả; tuần 12: chùm 3 đậu quả; tuần 14: quả chùm 1 bắt đầu chuyển màu",en:"Week 9: truss 1 set fruit; week 12: truss 3 set fruit; week 14: truss 1 fruit starting to color"}},{cmd:"cat drain.log",out:{vi:"Tỷ lệ nước thoát 3 ngày gần nhất: 4%, 3%, 2%; EC nước thoát tăng từ 3.2 lên 5.6 mS/cm",en:"Drain fraction over the last 3 days: 4%, 3%, 2%; drain EC rising from 3.2 to 5.6 mS/cm"}},{cmd:"sensor lysimeter",out:{vi:"Cân lysimeter: lượng nước cây hút trung bình 1.8 lít/cây/ngày trong 5 ngày nắng gần nhất",en:"Lysimeter: average uptake 1.8 L per plant per day over the last 5 sunny days"}},{cmd:"cat recipe.txt",out:{vi:"TOM-SEED: vườn ươm; TOM-VEG: từ khi trồng đến khi chùm 1 đậu quả; TOM-FRUIT: từ khi chùm 1 đậu quả, tăng K và Ca, EC 3.0-3.5 mS/cm",en:"TOM-SEED: nursery; TOM-VEG: from transplanting until truss 1 sets fruit; TOM-FRUIT: from truss 1 fruit set, higher K and Ca, EC 3.0-3.5 mS/cm"}}]},crisis:{vi:"Chủ hợp tác xã nhắn: “Hôm qua đã phun thuốc trừ nhện ở dãy B, nhưng siêu thị cần 2 tấn cà chua sáng mai. Cứ thu hoạch cả dãy B và dán tem truy xuất như bình thường.”",en:"The cooperative owner texts: “We sprayed miticide in row B yesterday, but the supermarket needs 2 tonnes of tomatoes tomorrow morning. Harvest row B too and apply the usual traceability labels.”"},options:{safe:{vi:"Không thu hoạch dãy B trước khi hết thời gian cách ly trên nhãn thuốc, khoanh vùng và ghi nhật ký; báo Giám đốc kỹ thuật, lấy hàng từ dãy không phun và báo người mua sản lượng thực tế.",en:"Do not harvest row B before the label's pre-harvest interval ends; mark and log the area, inform the Head of Crop Technology, supply from unsprayed rows and tell the buyer the real volume."},shortcut:{vi:"Thu hoạch cả dãy B cho đủ 2 tấn và dán tem truy xuất như bình thường.",en:"Harvest row B too to reach 2 tonnes and label it as usual."},wait:{vi:"Không nói gì, để đội thu hoạch tự quyết định hái dãy nào.",en:"Say nothing and let the picking crew decide which rows to harvest."}},questions:{vi:["Vì sao GH-0314 phải chuyển sang công thức TOM-FRUIT? Dữ liệu nào trong nhật ký cây trồng chứng minh?","Trình bày cách tính tổng lượng tưới và rủi ro khi giá thể bị tích muối do thiếu nước thoát."],en:["Why must GH-0314 switch to recipe TOM-FRUIT? Which crop log data proves it?","Explain how you calculated total irrigation and the risk of salt build-up in the substrate when drainage is too low."]},hints:{vi:["Đọc nhật ký cây trồng để xác định giai đoạn sinh trưởng rồi so với lịch dinh dưỡng đã duyệt.","Chia lượng cây hút cho phần nước được giữ lại theo SOP mục 3.2 trước khi nhân với số cây.","Đọc lại SOP mục 4.2: không thu hoạch khi chưa hết thời gian cách ly thuốc bảo vệ thực vật."],en:["Read the crop log to identify the growth stage, then compare it with the approved nutrient schedule.","Divide uptake by the retained share of water in SOP 3.2 before multiplying by the number of plants.","Re-read SOP 4.2: never harvest before the pesticide pre-harvest interval has passed."]}},learning:{summary:{vi:"Kỹ sư nông nghiệp thông minh thiết kế và vận hành hệ thống canh tác công nghệ cao: nhà màng, tưới nhỏ giọt kết hợp bón phân, cảm biến IoT, trạm thời tiết và bộ điều khiển khí hậu. Kỹ sư phân tích dữ liệu cây trồng để tối ưu năng suất, tiết kiệm nước, phân bón và bảo đảm nông sản an toàn, truy xuất được nguồn gốc.",en:"A smart agriculture and IoT agronomist designs and runs high-tech growing systems: greenhouses, drip fertigation, IoT sensors, weather stations and climate controllers. The agronomist analyzes crop data to raise yield, save water and fertilizer, and ensure produce is safe and traceable."},responsibilities:{vi:["Lập kế hoạch canh tác, lịch dinh dưỡng và chiến lược tưới theo giai đoạn sinh trưởng.","Lắp đặt, hiệu chuẩn cảm biến EC, pH, độ ẩm giá thể, bức xạ, nhiệt độ và độ ẩm không khí.","Giám sát dữ liệu IoT, điều chỉnh khí hậu nhà màng, lượng tưới và tỷ lệ nước thoát.","Quản lý dịch hại tổng hợp (IPM), nhật ký phun thuốc và thời gian cách ly.","Ghi chép nhật ký canh tác phục vụ chứng nhận VietGAP và truy xuất nguồn gốc."],en:["Plan crops, nutrient schedules and irrigation strategies by growth stage.","Install and calibrate EC, pH, substrate moisture, radiation, temperature and humidity sensors.","Monitor IoT data and adjust greenhouse climate, irrigation and drain fraction.","Run integrated pest management (IPM), spray records and pre-harvest intervals.","Keep crop records for VietGAP certification and traceability."]},competencies:[{name:{vi:"Dinh dưỡng & tưới cây trồng",en:"Crop nutrition & irrigation"},desc:{vi:"Chọn công thức theo giai đoạn, điều chỉnh EC, pH và lượng tưới theo bức xạ, nước thoát.",en:"Choose stage-based recipes and tune EC, pH and irrigation to radiation and drainage."}},{name:{vi:"Hệ thống IoT & điều khiển",en:"IoT & control systems"},desc:{vi:"Cấu hình cảm biến, bộ điều khiển, truyền dữ liệu và cảnh báo khi thông số vượt ngưỡng.",en:"Configure sensors, controllers, data links and alerts when values go out of range."}},{name:{vi:"Phân tích dữ liệu canh tác",en:"Crop data analysis"},desc:{vi:"Đọc xu hướng EC, nước thoát, khí hậu để phát hiện sớm stress và tối ưu năng suất.",en:"Read EC, drainage and climate trends to spot stress early and optimize yield."}},{name:{vi:"Quản lý dịch hại tổng hợp",en:"Integrated pest management"},desc:{vi:"Giám sát bằng bẫy, ưu tiên biện pháp sinh học và dùng thuốc đúng nhãn, đúng thời gian cách ly.",en:"Monitor with traps, favor biological control and use pesticides per label and interval."}},{name:{vi:"An toàn thực phẩm & tuân thủ",en:"Food safety & compliance"},desc:{vi:"Ghi chép đầy đủ, từ chối thu hoạch sai quy định và bảo đảm tem truy xuất trung thực.",en:"Keep complete records, refuse non-compliant harvests and keep traceability labels truthful."}}],knowledge:{vi:["Luật Trồng trọt số 31/2018/QH14 và Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13.","TCVN 11892-1:2017 Thực hành nông nghiệp tốt (VietGAP) - Phần 1: Trồng trọt.","Nguyên lý dinh dưỡng cây trồng trên giá thể: EC, pH, tỷ lệ N:K, cân bằng Ca, Mg và tỷ lệ nước thoát.","Phương pháp FAO-56 Penman-Monteith tính bốc thoát hơi nước tham chiếu ET0 và hệ số cây trồng Kc.","Giao thức IoT trong nông nghiệp: MQTT, LoRaWAN, Modbus và nguyên tắc hiệu chuẩn cảm biến.","Quản lý dịch hại tổng hợp (IPM) và thời gian cách ly ghi trên nhãn thuốc bảo vệ thực vật."],en:["Crop Production Law No. 31/2018/QH14 and Plant Protection and Quarantine Law No. 41/2013/QH13.","TCVN 11892-1:2017 Good Agricultural Practices (VietGAP) - Part 1: Crop production.","Substrate crop nutrition principles: EC, pH, N:K ratio, Ca and Mg balance and drain fraction.","The FAO-56 Penman-Monteith method for reference evapotranspiration ET0 and crop coefficient Kc.","Agricultural IoT protocols: MQTT, LoRaWAN, Modbus and sensor calibration principles.","Integrated pest management (IPM) and the pre-harvest intervals on pesticide labels."]},tools:["Bộ điều khiển khí hậu và tưới nhà màng","Cảm biến EC, pH, độ ẩm giá thể","Cân lysimeter và khay đo nước thoát","Trạm thời tiết tự động","Nền tảng IoT và bảng giám sát dữ liệu","Phần mềm nhật ký canh tác và truy xuất nguồn gốc"],kpis:{vi:["Năng suất thương phẩm (kg/m2) so với kế hoạch.","Lượng nước và phân bón sử dụng trên mỗi kg sản phẩm.","Tỷ lệ lô hàng đạt kiểm nghiệm dư lượng thuốc bảo vệ thực vật (mục tiêu 100%).","Tỷ lệ cảm biến hoạt động ổn định và được hiệu chuẩn đúng hạn."],en:["Marketable yield (kg/m2) against plan.","Water and fertilizer used per kg of produce.","Share of lots passing pesticide residue tests (target 100%).","Share of sensors online and calibrated on schedule."]},day:[{time:"06:30",vi:"Xem bảng giám sát: nhiệt độ đêm, độ ẩm, EC, pH và cảnh báo của bộ điều khiển.",en:"Review the dashboard: night temperature, humidity, EC, pH and controller alerts."},{time:"08:00",vi:"Đo nước thoát, EC thoát tại khay mẫu và điều chỉnh chiến lược tưới trong ngày.",en:"Measure drain volume and EC at sample trays and adjust the day's irrigation strategy."},{time:"10:00",vi:"Kiểm tra đồng ruộng: sinh trưởng, đậu quả, bẫy dính côn trùng và dấu hiệu bệnh.",en:"Walk the crop: growth, fruit set, sticky traps and disease symptoms."},{time:"14:00",vi:"Hiệu chuẩn cảm biến, bảo trì đầu nhỏ giọt và bộ lọc.",en:"Calibrate sensors and maintain drippers and filters."},{time:"16:30",vi:"Ghi nhật ký canh tác và lập kế hoạch thu hoạch theo thời gian cách ly.",en:"Update crop records and plan harvests around pre-harvest intervals."}],mistakes:{vi:["Giữ công thức sinh trưởng thân lá khi cây đã vào giai đoạn nuôi quả, gây quả nhỏ và thối đáy quả.","Tính lượng tưới chỉ bằng lượng cây hút, không có nước thoát làm giá thể tích muối.","Thu hoạch trước khi hết thời gian cách ly để kịp đơn hàng, gây rủi ro dư lượng thuốc."],en:["Keeping the vegetative recipe after fruit set, causing small fruit and blossom-end rot.","Setting irrigation equal to uptake with no drainage, so salts build up in the substrate.","Harvesting before the pre-harvest interval to meet an order, risking pesticide residues."]},career:[{vi:"Kỹ thuật viên nông nghiệp công nghệ cao",en:"High-tech agriculture technician"},{vi:"Kỹ sư nông nghiệp thông minh",en:"Smart agriculture agronomist"},{vi:"Trưởng bộ phận canh tác nhà màng",en:"Greenhouse production manager"},{vi:"Giám đốc kỹ thuật nông nghiệp",en:"Head of Agricultural Technology"}],glossary:[{term:"EC",vi:"Độ dẫn điện của dung dịch, phản ánh tổng nồng độ muối dinh dưỡng, đơn vị mS/cm.",en:"Electrical conductivity of the solution, showing total nutrient salt concentration, in mS/cm."},{term:"Drain fraction",vi:"Tỷ lệ nước thoát: phần trăm lượng nước tưới chảy ra khỏi giá thể, giúp rửa muối dư.",en:"The share of applied water draining out of the substrate, flushing excess salts."},{term:"Fertigation",vi:"Tưới kết hợp bón phân: hòa phân vào nước tưới và cấp qua hệ thống nhỏ giọt.",en:"Applying dissolved fertilizer through the drip irrigation system."},{term:"Lysimeter",vi:"Thiết bị cân liên tục khay cây để đo lượng nước cây hút và lượng nước thoát.",en:"A device that continuously weighs a plant tray to measure uptake and drainage."},{term:"PHI",vi:"Thời gian cách ly: số ngày tối thiểu từ lần phun thuốc cuối cùng đến khi được thu hoạch.",en:"Pre-harvest interval: the minimum number of days between the last spray and harvest."}],quiz:[{q:{vi:"Cây hút 2.1 lít/cây/ngày, tỷ lệ nước thoát mục tiêu 30%. Lượng tưới mỗi cây là bao nhiêu?",en:"Plants take up 2.1 L per plant per day with a 30% target drain fraction. How much should each plant receive?"},options:{vi:["2.1 lít","2.73 lít","3.0 lít","1.47 lít"],en:["2.1 L","2.73 L","3.0 L","1.47 L"]},answer:2,explain:{vi:"Lượng tưới = 2.1 / (1 - 0.3) = 3.0 lít; nhân 1.3 là cách tính sai thường gặp.",en:"Irrigation = 2.1 / (1 - 0.3) = 3.0 L; multiplying by 1.3 is a common mistake."}},{q:{vi:"EC nước thoát tăng liên tục và tỷ lệ nước thoát chỉ còn 2%. Nguyên nhân hợp lý nhất là gì?",en:"Drain EC keeps rising and the drain fraction is only 2%. What is the most likely cause?"},options:{vi:["Tưới thiếu, muối tích tụ trong giá thể","Tưới quá nhiều","Cảm biến pH hỏng","Nhiệt độ đêm thấp"],en:["Under-irrigation causing salt build-up","Over-irrigation","Faulty pH sensor","Low night temperature"]},answer:0,explain:{vi:"Nước thoát quá ít không đủ rửa muối nên EC vùng rễ tăng; cần tăng lượng tưới để đạt tỷ lệ thoát mục tiêu.",en:"Too little drainage cannot flush salts so root-zone EC rises; increase irrigation to reach the target drain."}},{q:{vi:"Một khu vừa phun thuốc nhưng khách cần hàng gấp trong thời gian cách ly. Phương án đúng là gì?",en:"An area was just sprayed but a customer needs produce urgently within the pre-harvest interval. What is right?"},options:{vi:["Thu hoạch vì đơn hàng gấp","Rửa kỹ quả rồi thu hoạch","Trộn với hàng khu khác cho đủ số lượng","Chờ hết thời gian cách ly, lấy hàng khu không phun và báo người mua"],en:["Harvest because the order is urgent","Wash the fruit well and harvest","Mix it with produce from other areas","Wait out the interval, supply from unsprayed areas and inform the buyer"]},answer:3,explain:{vi:"Thời gian cách ly bảo đảm dư lượng dưới giới hạn cho phép; rửa không thay thế được và trộn hàng làm sai truy xuất.",en:"The interval keeps residues below limits; washing is no substitute and mixing breaks traceability."}},{q:{vi:"Giao thức nào phù hợp truyền dữ liệu cảm biến tầm xa, tiêu thụ điện thấp trên cánh đồng rộng?",en:"Which protocol suits long-range, low-power sensor data across large fields?"},options:{vi:["HDMI","LoRaWAN","USB","Bluetooth Classic"],en:["HDMI","LoRaWAN","USB","Bluetooth Classic"]},answer:1,explain:{vi:"LoRaWAN là mạng diện rộng công suất thấp, truyền được vài km với pin dùng nhiều năm.",en:"LoRaWAN is a low-power wide-area network reaching several kilometers on years of battery life."}}],tools_en:["Greenhouse climate and irrigation controller","EC, pH and substrate moisture sensors","Weighing lysimeter and drainage trays","Automatic weather station","IoT platform and monitoring dashboard","Farm records and traceability software"]}}})})(window.KKR);
